import { createChart } from '../test/ut/core/utHelper';
import { getECData } from '../src/util/innerStore';
import SunburstPiece from '../src/chart/sunburst/SunburstPiece';

describe('sunburst-relative-focus', function () {

    const data = [{
        name: 'grandA',
        children: [{
            name: 'parentA',
            children: [
                { name: 'childA', value: 10 },
                { name: 'childB', value: 20 }
            ]
        }]
    }, {
        name: 'grandB',
        value: 30
    }];

    function getPieceFocus(chart: ReturnType<typeof createChart>, name: string): unknown {
        const seriesModel = chart.getModel().getSeriesByIndex(0);
        const view = chart.getViewOfSeriesModel(seriesModel);
        let found: unknown = null;
        view.group.traverse(function (el: SunburstPiece) {
            if (el instanceof SunburstPiece && el.node && el.node.name === name) {
                found = getECData(el).focus;
            }
        });
        return found;
    }

    function uniqSorted(indices: number[]): number[] {
        return indices.filter(function (v, i) {
            return indices.indexOf(v) === i;
        }).sort(function (a, b) {
            return a - b;
        });
    }

    it('focus relative includes both ancestors and descendants', function () {
        const chart = createChart();
        chart.setOption({
            series: [{
                type: 'sunburst',
                emphasis: {
                    focus: 'relative'
                },
                data: data
            }]
        });

        const focus = getPieceFocus(chart, 'parentA') as number[];
        expect(focus).toBeTruthy();
        // virtual root(0) + grandA(1) + parentA(2) + childA(3) + childB(4),
        // but not the unrelated grandB(5)
        expect(uniqSorted(focus)).toEqual([0, 1, 2, 3, 4]);
    });

    it('other focus strategies keep their semantics', function () {
        const chart = createChart();
        chart.setOption({
            series: [{
                type: 'sunburst',
                emphasis: {
                    focus: 'ancestor'
                },
                data: data
            }]
        });
        // virtual root(0) + grandA(1) + parentA(2) only
        expect(uniqSorted(getPieceFocus(chart, 'parentA') as number[])).toEqual([0, 1, 2]);

        chart.setOption({
            series: [{
                type: 'sunburst',
                emphasis: {
                    focus: 'descendant'
                },
                data: data
            }]
        });
        // parentA(2) + childA(3) + childB(4) only
        expect(uniqSorted(getPieceFocus(chart, 'parentA') as number[])).toEqual([2, 3, 4]);
    });
});

